#!/usr/bin/env bun
/**
 * Copies the built MCP App (dist/index.html) to where workgraph-mcp embeds it
 * (crates/workgraph-mcp/assets/plan-review.html, `include_str!`), marked
 * generated. Cargo can't run the Vite build, so the bundle is committed, and
 * `just factory-check` rebuilds it and fails on drift (`--check`).
 *
 * `just factory-review-build` runs the build and this; `--check` compares
 * instead of writing.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const HEADER =
  "<!-- @generated by packages/factory-plan-review (`just factory-review-build`). Do not edit. -->\n";
const here = join(import.meta.dir, "..");
const built = join(here, "dist", "index.html");
const target = join(here, "..", "..", "crates", "workgraph-mcp", "assets", "plan-review.html");

const want = HEADER + readFileSync(built, "utf8");
if (process.argv.includes("--check")) {
  let have = "";
  try {
    have = readFileSync(target, "utf8");
  } catch {}
  if (have !== want) {
    console.error(
      "crates/workgraph-mcp/assets/plan-review.html is stale: run `just factory-review-build` and commit it.",
    );
    process.exit(1);
  }
} else {
  writeFileSync(target, want);
  console.log(`→ wrote ${target}`);
}
